from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
from airflow.api.client.local_client import Client
from typing import Dict, Any

router = APIRouter(prefix="/orchestration/airflow")

class TriggerDagPayload(BaseModel):
    dag_id: str
    conf: Dict[str, Any] = {}

@router.post("/trigger")
async def trigger_airflow_dag(
    payload: TriggerDagPayload,
    airflow_client: Client = Depends(get_airflow_client),
    dag_policy: DagPolicyService = Depends(get_dag_policy_service),
    current_user: User = Depends(get_current_user)
):
    if not dag_policy.is_tenant_dag(current_user.tenant_id, payload.dag_id):
        raise HTTPException(status_code=403, detail="Forbidden: Unauthorized to trigger this DAG")

    try:
        dag_run = airflow_client.trigger_dag(
            dag_id=payload.dag_id,
            conf=payload.conf
        )
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to trigger DAG: {str(e)}")

    return {
        "status": "triggered",
        "dag_id": payload.dag_id,
        "execution_date": str(dag_run.get("execution_date"))
    }
